            routes.append(current)
            current = [c]
            current_load = d
        else:
            current.append(c)
            current_load += d

    if current:
        routes.append(current)

    # ---------- repair: split oversized routes if needed ----------
    repaired = []
    for r in routes:
        load = route_load(r, demands)
        if load <= cap:
            repaired.append(r)
            continue
        # deterministic split by greedy fill
        part = []
        part_load = 0
        for c in r:
            d = demand_of(demands, c)
            if part and part_load + d > cap:
                repaired.append(part)
                part = [c]
                part_load = d
            else:
                part.append(c)
                part_load += d
        if part:
            repaired.append(part)

    routes = repaired

    # ---------- local improvement: route-wise insertion / 2-opt ----------
    for i in range(len(routes)):
        routes[i] = two_opt_route(routes[i], depot, distm, coords)

    # ---------- cross-route repair: relocate customers if feasible and beneficial ----------
    improved = True
    while improved:
        improved = False
        best_move = None
        best_gain = 0
        loads = [route_load(r, demands) for r in routes]
        for i in range(len(routes)):
            ri = routes[i]
            for p, c in enumerate(ri):
                dc = demand_of(demands, c)
                before_i = route_cost(ri, depot, distm, coords)
                # cost after removing c
                ri_removed = ri[:p] + ri[p + 1:]
                if ri_removed:
                    after_remove = route_cost(ri_removed, depot, distm, coords)
                else:
                    after_remove = 0
                remove_gain = before_i - after_remove
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if loads[j] + dc > cap:
                        continue
                    rj = routes[j]
                    base_j = route_cost(rj, depot, distm, coords)
                    for pos in range(len(rj) + 1):
                        cand_j = rj[:pos] + [c] + rj[pos:]
                        add_cost = route_cost(cand_j, depot, distm, coords) - base_j
                        gain = remove_gain - add_cost
                        key = (gain, -dc, c, i, j, p, pos)
                        if gain > best_gain + 1e-12 or (abs(gain - best_gain) <= 1e-12 and best_move is not None and key < best_move[0]):
                            best_gain = gain
                            best_move = (key, i, j, p, pos, c)
        if best_move is not None and best_gain > 1e-12:
            _, i, j, p, pos, c = best_move
            routes[i].pop(p)
            routes[j].insert(pos, c)
            if not routes[i]:
                del routes[i]
            for k in range(len(routes)):
                routes[k] = two_opt_route(routes[k], depot, distm, coords)
            improved = True

    # ---------- final construction sanity: if any missing (shouldn't happen), append ----------
    seen = set()
    for r in routes:
        for c in r:
            seen.add(c)
    missing = [c for c in customers if c not in seen]
    for c in missing:
        d = demand_of(demands, c)
        placed = False
        best_idx = None
        best_pos = None
        best_key = None
        for i, r in enumerate(routes):
            if route_load(r, demands) + d > cap:
                continue
            for pos in range(len(r) + 1):
                cand = r[:pos] + [c] + r[pos:]
                key = (route_cost(cand, depot, distm, coords), len(cand), i, pos)
                if best_key is None or key < best_key:
                    best_key = key
                    best_idx = i
                    best_pos = pos
        if best_idx is None:
            routes.append([c])
        else:
            routes[best_idx].insert(best_pos, c)

    return routes
